import {
  ID13
} from "./repository-cache-1hyfwtsr.js";

// src/plugin/provider/amazon-bedrock.ts
import { Effect } from "effect";
import path from "node:path";
import { define } from "@opencode/plugin/effect/plugin";
import { FSUtil } from "@opencode/util/fs-util";
import { Global } from "@opencode/util/global";
var CHAIN_ENV = [
  "AWS_PROFILE",
  "AWS_ACCESS_KEY_ID",
  "AWS_WEB_IDENTITY_TOKEN_FILE",
  "AWS_CONTAINER_CREDENTIALS_RELATIVE_URI",
  "AWS_CONTAINER_CREDENTIALS_FULL_URI"
];
var isBedrock = (item) => item.package.startsWith("@opencode/ai/providers/amazon-bedrock");
var AmazonBedrockPlugin2 = define({
  id: "opencode.provider.amazon.bedrock",
  effect: Effect.fn(function* (ctx) {
    const fs = yield* FSUtil.Service;
    const paths = [
      process.env.AWS_CONFIG_FILE ?? path.join(Global.Path.home, ".aws", "config"),
      process.env.AWS_SHARED_CREDENTIALS_FILE ?? path.join(Global.Path.home, ".aws", "credentials")
    ];
    const files = yield* Effect.all(paths.map((file) => fs.readFileStringSafe(file).pipe(Effect.orElseSucceed(() => {
      return;
    }))));
    const profiles = Array.from(new Set(files.flatMap((content, index) => Array.from((content ?? "").matchAll(/^\s*\[([^\]\r\n]+)\]/gm)).flatMap((match) => {
      const section = match[1].trim();
      if (index === 1 || section === "default")
        return [section];
      return section.startsWith("profile ") ? [section.slice(8).trim()] : [];
    })))).filter(Boolean).toSorted();
    yield* ctx.integration.transform((editor) => {
      editor.method.update({
        integrationID: ID13.amazonBedrock,
        method: { type: "env", names: ["AWS_BEARER_TOKEN_BEDROCK"] }
      });
      editor.method.update({
        integrationID: ID13.amazonBedrock,
        method: { type: "key", label: "Bedrock API key" }
      });
      editor.method.update({
        integrationID: ID13.amazonBedrock,
        method: {
          id: "aws-profile",
          type: "external",
          label: "AWS profile (SSO or named profile)",
          form: [
            {
              key: "profile",
              type: "string",
              title: "AWS profile",
              description: profiles.length ? `Found ${profiles.length} profile${profiles.length === 1 ? "" : "s"} in your AWS configuration.` : "No profiles found in your AWS configuration.",
              required: true,
              minLength: 1,
              pattern: "\\S",
              placeholder: "Profile name",
              custom: true,
              options: profiles.map((profile) => ({ value: profile, label: profile }))
            }
          ]
        }
      });
    });
    yield* ctx.provider.transform((evt) => {
      for (const item of evt.list()) {
        if (!isBedrock(item.provider))
          continue;
        evt.update(item.provider.id, (provider) => {
          const settings = provider.settings ?? {};
          const chain = typeof settings.profile === "string" || CHAIN_ENV.some((name) => process.env[name]);
          if (chain && provider.activation === "auto")
            provider.activation = "enabled";
          const region = process.env.AWS_REGION ?? process.env.AWS_DEFAULT_REGION ?? "us-east-1";
          provider.settings = {
            ...settings,
            ...typeof settings.region !== "string" ? { region } : {},
            ...typeof settings.baseURL !== "string" && typeof settings.endpoint === "string" ? { baseURL: settings.endpoint } : {}
          };
          delete provider.settings.endpoint;
        });
      }
    });
  })
});

export { AmazonBedrockPlugin2 };
